import React, { useMemo, useState } from "react";
import { TEAM_COLOR_PALETTE } from "../../../state/teamSettings";
import TeamsSettingsPanel from "./TeamsSettingsPanel";

function defaultTeamStub(index, total) {
  const letter = String.fromCharCode(65 + (index % 26));
  const palette = TEAM_COLOR_PALETTE[index % TEAM_COLOR_PALETTE.length];
  return {
    id: `team-${Date.now()}-${index}`,
    name: `Team ${letter}`,
    color: palette.hex,
    letter,
    createdAt: Date.now(),
    isActive: true,
  };
}

export default function TeamsConfigModal({
  isOpen,
  onClose,
  onSave,
  initialTeams = [],
  teamsSettings,
  onTeamsSettingsChange,
  minTeams = 2,
  maxTeams = 8,
}) {
  const [count, setCount] = useState(() =>
    Math.min(maxTeams, Math.max(minTeams, initialTeams?.length || minTeams))
  );
  const [draftTeams, setDraftTeams] = useState(() =>
    initialTeams?.length ? initialTeams : Array.from({ length: minTeams }, (_, i) => defaultTeamStub(i, minTeams))
  );

  React.useEffect(() => {
    if (!isOpen) return;
    if (initialTeams?.length) {
      setDraftTeams(initialTeams.map((t) => ({ ...t })));
      setCount(initialTeams.length);
    } else {
      const n = Math.max(minTeams, count);
      setDraftTeams(Array.from({ length: n }, (_, i) => defaultTeamStub(i, n)));
      setCount(n);
    }
  }, [isOpen]); // eslint-disable-line react-hooks/exhaustive-deps -- intentional open-only reset

  const usedColors = useMemo(() => new Set(draftTeams.map((t) => t.color)), [draftTeams]);

  const resize = (n) => {
    const next = Math.min(maxTeams, Math.max(minTeams, n));
    setCount(next);
    setDraftTeams((prev) => {
      if (next === prev.length) return prev;
      if (next > prev.length) {
        const add = [];
        for (let i = prev.length; i < next; i += 1) {
          add.push(defaultTeamStub(i, next));
        }
        return [...prev, ...add];
      }
      return prev.slice(0, next);
    });
  };

  const updateTeam = (idx, patch) => {
    setDraftTeams((prev) => {
      const copy = [...prev];
      copy[idx] = { ...copy[idx], ...patch };
      if (patch.name != null) {
        const ch = String(patch.name).trim().charAt(0).toUpperCase();
        copy[idx].letter = /[A-Z]/.test(ch) ? ch : copy[idx].letter;
      }
      return copy;
    });
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
      <div className="bg-white rounded-2xl shadow-xl max-w-lg w-full max-h-[90vh] overflow-hidden flex flex-col border border-slate-200">
        <div className="px-5 py-4 border-b border-slate-100 flex justify-between items-center">
          <h2 className="text-lg font-display text-slate-800">Team setup</h2>
          <button type="button" className="text-slate-400 hover:text-slate-600 text-xl leading-none" onClick={onClose}>
            ×
          </button>
        </div>
        <div className="px-5 py-4 overflow-y-auto flex-1 space-y-4 text-xs">
          <div>
            <span className="text-slate-600">Number of teams</span>
            <div className="flex flex-wrap gap-2 mt-2">
              {Array.from({ length: maxTeams - minTeams + 1 }, (_, i) => minTeams + i).map((n) => (
                <button
                  key={n}
                  type="button"
                  className={`px-3 py-1.5 rounded-full text-xs font-semibold ${
                    count === n ? "bg-pt-teal text-white" : "bg-slate-100 text-slate-600 hover:bg-slate-200"
                  }`}
                  onClick={() => resize(n)}
                >
                  {n}
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-3">
            {draftTeams.map((team, idx) => (
              <div
                key={team.id || idx}
                className="flex flex-wrap items-center gap-2 p-3 rounded-xl border border-slate-100 bg-slate-50/80"
              >
                <span
                  className="w-8 h-8 rounded-lg shrink-0 shadow-sm border border-white/50"
                  style={{ backgroundColor: team.color }}
                />
                <input
                  type="text"
                  className="flex-1 min-w-[120px] border rounded-lg px-2 py-1.5 text-sm"
                  value={team.name}
                  onChange={(e) => updateTeam(idx, { name: e.target.value })}
                />
                <div className="flex flex-wrap gap-1">
                  {TEAM_COLOR_PALETTE.map((c) => {
                    const disabled = usedColors.has(c.hex) && team.color !== c.hex;
                    return (
                      <button
                        key={c.key}
                        type="button"
                        title={c.label}
                        disabled={disabled}
                        className={`w-6 h-6 rounded-full border-2 ${
                          team.color === c.hex ? "border-slate-900 scale-110" : "border-transparent opacity-90"
                        } ${disabled ? "opacity-25 cursor-not-allowed" : "cursor-pointer"}`}
                        style={{ backgroundColor: c.hex }}
                        onClick={() => !disabled && updateTeam(idx, { color: c.hex })}
                      />
                    );
                  })}
                </div>
              </div>
            ))}
          </div>

          <details className="border border-slate-100 rounded-xl p-3 bg-white">
            <summary className="cursor-pointer font-semibold text-slate-700 text-[11px]">
              Team Settings (matching &amp; TV)
            </summary>
            <div className="mt-3 pt-3 border-t border-slate-100">
              <TeamsSettingsPanel
                teamsSettings={teamsSettings}
                onChange={(patch) => onTeamsSettingsChange?.(patch)}
                idPrefix="cfg"
              />
            </div>
          </details>
        </div>
        <div className="px-5 py-4 border-t border-slate-100 flex justify-end gap-2 bg-slate-50/80">
          <button
            type="button"
            className="px-4 py-2 rounded-full text-xs border border-slate-200 text-slate-600 hover:bg-white"
            onClick={onClose}
          >
            Cancel
          </button>
          <button
            type="button"
            className="px-4 py-2 rounded-full text-xs bg-pt-teal text-white font-semibold hover:bg-pt-teal/90"
            onClick={() => onSave?.(draftTeams)}
          >
            Save teams
          </button>
        </div>
      </div>
    </div>
  );
}
