import React, { useCallback, useEffect, useState } from "react";
import config from "../../config";
import { verifyLockPin } from "../../common/api/lockPin";

const KEYS = ["1", "2", "3", "4", "5", "6", "7", "8", "9"];

export default function LockScreen({ onUnlock }) {
  const [pin, setPin] = useState("");
  const [error, setError] = useState("");
  const [isVerifying, setIsVerifying] = useState(false);

  const submit = useCallback(
    async (value) => {
      const next = String(value || "").replace(/\D/g, "").slice(0, 6);
      if (next.length !== 6) {
        setError("Enter the 6-digit PIN.");
        return;
      }
      setIsVerifying(true);
      setError("");
      try {
        await verifyLockPin(next);
        onUnlock();
      } catch (err) {
        setError(err.message || "Incorrect PIN");
        setPin("");
      } finally {
        setIsVerifying(false);
      }
    },
    [onUnlock]
  );

  const append = useCallback(
    (digit) => {
      if (isVerifying) return;
      setError("");
      setPin((prev) => {
        const next = `${prev}${digit}`.slice(0, 6);
        if (next.length === 6) {
          setTimeout(() => {
            void submit(next);
          }, 0);
        }
        return next;
      });
    },
    [isVerifying, submit]
  );

  useEffect(() => {
    const onKey = (event) => {
      if (event.key >= "0" && event.key <= "9") {
        event.preventDefault();
        append(event.key);
      } else if (event.key === "Backspace") {
        event.preventDefault();
        setPin((prev) => prev.slice(0, -1));
      } else if (event.key === "Enter") {
        event.preventDefault();
        void submit(pin);
      } else if (event.key === "Escape") {
        setPin("");
        setError("");
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [append, pin, submit]);

  return (
    <div className="min-h-screen w-full bg-[#eef2f6] flex items-center justify-center p-4 font-body text-pt-navy">
      <div className="w-full max-w-sm bg-white rounded-3xl shadow-xl border border-slate-200/80 px-8 py-10 flex flex-col items-center">
        <img
          src={config.assetPath("logo.png")}
          alt={config.name}
          className="h-20 w-auto object-contain mb-5 bg-display rounded-2xl px-3 py-2"
        />
        <p className="text-[11px] font-semibold uppercase tracking-[0.28em] text-pt-teal">
          South Dinkers
        </p>
        <h1 className="text-2xl font-bold text-pt-navy mt-1">Sports Center</h1>
        <p className="text-sm text-slate-500 mt-2 mb-6">Staff PIN to open Dink Manager.</p>

        <div className="flex items-center gap-3 mb-2">
          {Array.from({ length: 6 }).map((_, idx) => (
            <span
              key={idx}
              className={`h-3 w-3 rounded-full ${idx < pin.length ? "bg-pt-navy" : "bg-slate-200"}`}
            />
          ))}
        </div>
        <p className="text-xs text-slate-400 mb-5">Enter 6-digit PIN.</p>
        {error && <p className="text-red-500 text-xs font-semibold mb-3">{error}</p>}

        <div className="grid grid-cols-3 gap-2.5 w-full">
          {KEYS.map((key) => (
            <button
              key={key}
              type="button"
              disabled={isVerifying}
              onClick={() => append(key)}
              className="h-14 rounded-xl border border-slate-200 bg-white text-xl font-bold text-pt-navy hover:bg-slate-50 active:scale-95 disabled:opacity-60"
            >
              {key}
            </button>
          ))}
          <button
            type="button"
            disabled={isVerifying}
            onClick={() => {
              setPin("");
              setError("");
            }}
            className="h-14 text-sm font-semibold text-slate-500 hover:text-pt-navy"
          >
            Clear
          </button>
          <button
            type="button"
            disabled={isVerifying}
            onClick={() => append("0")}
            className="h-14 rounded-xl border border-slate-200 bg-white text-xl font-bold text-pt-navy hover:bg-slate-50 active:scale-95 disabled:opacity-60"
          >
            0
          </button>
          <button
            type="button"
            disabled={isVerifying}
            onClick={() => void submit(pin)}
            className="h-14 rounded-xl bg-pt-teal text-white text-sm font-bold hover:bg-pt-teal/90 active:scale-95 disabled:opacity-60"
          >
            {isVerifying ? "…" : "Unlock"}
          </button>
        </div>

        <p className="text-[11px] text-slate-400 text-center mt-6 leading-relaxed">
          Refresh or reload locks Dink Manager again. Anyone with the link still needs this PIN.
        </p>
      </div>
    </div>
  );
}
