import React, { useEffect } from 'react';

/**
 * A standardized modal for confirmations.
 *
 * @param {boolean} isOpen - Whether the modal is visible.
 * @param {string} title - The main heading (e.g., "Are you sure?").
 * @param {string} message - The explanatory text.
 * @param {string} confirmLabel - Text for the confirm button.
 * @param {string} cancelLabel - Text for the cancel button.
 * @param {function} onConfirm - Callback when user confirms.
 * @param {function} onCancel - Callback when user cancels.
 * @param {boolean} isDestructive - If true, confirm button is red.
 */
export default function ConfirmationModal({
    isOpen,
    title,
    message,
    confirmLabel = "Confirm",
    cancelLabel = "Cancel",
    onConfirm,
    onCancel,
    isDestructive = false
}) {
    // Close on Escape
    useEffect(() => {
        if (!isOpen) return;
        const onKey = (e) => e.key === "Escape" && onCancel();
        window.addEventListener("keydown", onKey);
        return () => window.removeEventListener("keydown", onKey);
    }, [isOpen, onCancel]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            {/* Backdrop */}
            <div
                className="absolute inset-0 bg-black/50 backdrop-blur-sm transition-opacity"
                onClick={onCancel}
            />

            {/* Modal Content */}
            <div className="relative bg-white rounded-xl shadow-2xl w-full max-w-md p-6 transform transition-all scale-100 flex flex-col gap-4">

                {/* Header */}
                <div>
                    <h3 className={`text-xl font-bold ${isDestructive ? "text-red-600" : "text-slate-900"}`}>
                        {title}
                    </h3>
                    {message && (
                        <p className="mt-2 text-sm text-slate-600 leading-relaxed">
                            {message}
                        </p>
                    )}
                </div>

                {/* Actions */}
                <div className="flex items-center justify-end gap-3 mt-4">
                    {cancelLabel && (
                        <button
                            onClick={onCancel}
                            className="px-4 py-2 rounded-lg text-sm font-medium text-slate-700 hover:bg-slate-100 transition-colors"
                        >
                            {cancelLabel}
                        </button>
                    )}
                    <button
                        onClick={onConfirm}
                        className={`px-4 py-2 rounded-lg text-sm font-medium text-white shadow-sm transition-transform active:scale-95 ${isDestructive
                            ? "bg-red-600 hover:bg-red-700"
                            : "bg-blue-600 hover:bg-blue-700"
                            }`}
                    >
                        {confirmLabel}
                    </button>
                </div>
            </div>
        </div>
    );
}
