import React from "react";
import ReactDOM from "react-dom/client";
import { createHashRouter, RouterProvider } from "react-router-dom";
import App from "./App";
import "./index.css";
import { AppStateProvider } from "./app/providers";
import { seedIfEmpty } from "./state/seed";

// Queue/settings persist in IndexedDB (hydrated before first render).
seedIfEmpty();

const router = createHashRouter([
  {
    path: "/*",
    element: <App />,
  },
]);

ReactDOM.createRoot(document.getElementById("root")).render(
  <React.StrictMode>
    <AppStateProvider>
      <RouterProvider
        router={router}
        future={{
          v7_startTransition: true,
          v7_relativeSplatPath: true,
          v7_normalizeFormMethod: true,
          v7_fetcherPersist: true,
        }}
      />
    </AppStateProvider>
  </React.StrictMode>
);

if ("serviceWorker" in navigator) {
  const isLocalhost =
    window.location.hostname === "localhost" ||
    window.location.hostname === "127.0.0.1" ||
    window.location.hostname === "[::1]";

  if (process.env.NODE_ENV === "production" && !isLocalhost) {
    let refreshing = false;
    const hadController = !!navigator.serviceWorker.controller;
    navigator.serviceWorker.addEventListener("controllerchange", () => {
      if (!hadController || refreshing) return;
      refreshing = true;
      window.location.reload();
    });
    window.addEventListener("load", () => {
      navigator.serviceWorker.register(`${process.env.PUBLIC_URL}/sw.js`).catch(() => {
        // Non-blocking: app should still work even if SW registration fails.
      });
    });
  } else {
    // Prevent dev/HMR + service-worker conflicts that can cause repeated refresh/revalidation loops.
    navigator.serviceWorker.getRegistrations().then((registrations) => {
      registrations.forEach((registration) => registration.unregister());
    });
  }
}


