import React from "react";
import { SideNav } from "../features/layout";
import config from "../config";

export default function AppShell({ children }) {
  const [collapsed, setCollapsed] = React.useState(false);
  const [mobileNavOpen, setMobileNavOpen] = React.useState(false);

  return (
    <div className="w-full h-screen flex overflow-hidden admin-page-bg">
      <SideNav
        collapsed={collapsed}
        onToggle={() => setCollapsed((v) => !v)}
        mobileOpen={mobileNavOpen}
        onMobileClose={() => setMobileNavOpen(false)}
      />
      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="px-4 py-2.5 md:px-5 md:py-3 bg-display border-b border-white/10 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3 md:gap-3.5">
            <button
              type="button"
              onClick={() => setMobileNavOpen(true)}
              className="md:hidden p-2 -ml-2 text-white hover:bg-white/10 rounded-md"
            >
              <span className="text-2xl leading-none">☰</span>
            </button>

            <img
              src={config.assetPath("logo.png")}
              alt={config.name}
              className="h-10 md:h-14 w-auto object-contain"
            />
            <div className="flex flex-col leading-none justify-center">
              <span className="text-sm md:text-lg text-white font-bold tracking-wide truncate max-w-[40vw] md:max-w-xs">
                {config.name}
              </span>
              <span className="text-[8px] text-[#C9A582] uppercase tracking-[0.25em] font-medium mt-0.5">
                {config.tagline || "Admin"}
              </span>
            </div>
          </div>
        </header>
        <div className="flex-1 min-h-0 overflow-hidden relative flex flex-col">{children}</div>
      </main>
    </div>
  );
}
