import React from "react";

// Simple SVG sparkline component
const Sparkline = ({ data = [], stroke = "#10b981" }) => {
    if (!data.length) return null;
    const safe = data.map((v) => {
        const n = Number(v);
        return Number.isFinite(n) ? n : 0;
    });
    const max = Math.max(...safe, 1);
    const min = Math.min(...safe);
    const range = max - min || 1;
    const width = 100;
    const height = 30;
    const denom = Math.max(safe.length - 1, 1);

    const points = safe
        .map((val, i) => {
            const x = (i / denom) * width;
            const y = height - ((val - min) / range) * height;
            return `${x},${y}`;
        })
        .join(" ");
    const lastY = height - ((safe[safe.length - 1] - min) / range) * height;

    return (
        <svg width="100%" height="100%" viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none" className="overflow-hidden">
            <polyline points={points} fill="none" strokeWidth="2" stroke={stroke} strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke" />
            <circle cx={width} cy={lastY} r="2.5" fill={stroke} />
        </svg>
    );
};

export default function MetricTile({
    title,
    value,
    subtext,
    icon,
    trend,
    chartData,
    onViewReport,
    className = "",
    colorClass = "text-slate-900",
    sideContent = null
}) {
    return (
        <div
            onClick={onViewReport}
            className={`p-6 bg-white rounded-2xl border border-pt-teal/10 shadow-sm hover:shadow-md transition-all cursor-pointer relative overflow-hidden group ${className}`}
        >
            <div className="flex items-start justify-between mb-4">
                <div>
                    <p className="text-xs font-semibold uppercase tracking-wider text-slate-500 mb-1">{title}</p>
                    <h3 className={`text-2xl font-bold ${colorClass}`}>{value}</h3>
                </div>
                {icon && (
                    <div className="p-2 rounded-lg bg-slate-50 text-pt-teal border border-slate-100">
                        {icon}
                    </div>
                )}
            </div>

            {/* Middle: Content/Chart */}
            <div className="flex-1 min-h-[40px] flex items-end justify-between gap-4">
                <div className="flex flex-col justify-end">
                    {subtext && <p className="text-[11px] text-slate-500">{subtext}</p>}
                    {trend && (
                        <div className={`flex items-center gap-1 text-xs font-medium ${trend.direction === 'up' ? 'text-emerald-600' : trend.direction === 'down' ? 'text-rose-600' : 'text-slate-500'}`}>
                            <span>{trend.direction === 'up' ? '↑' : trend.direction === 'down' ? '↓' : '•'}</span>
                            {trend.value}
                        </div>
                    )}
                </div>

                {sideContent && (
                    <div className="flex-shrink-0">
                        {sideContent}
                    </div>
                )}

                {chartData && (
                    <div className="w-24 h-10">
                        <Sparkline data={chartData} stroke={colorClass.includes('emerald') ? '#059669' : colorClass.includes('rose') ? '#e11d48' : '#6366f1'} />
                    </div>
                )}
            </div>

            {/* Footer: Action */}
            <div className="mt-4 pt-3 border-t border-slate-50 flex justify-end">
                <button
                    type="button"
                    onClick={(e) => {
                        e.stopPropagation();
                        onViewReport?.();
                    }}
                    className="text-[11px] font-medium text-pt-teal hover:text-pt-navy transition-colors flex items-center gap-1"
                >
                    View details →
                </button>
            </div>
        </div>
    );
}
