import { CURRENT_STATE_VERSION, normalizeStateMeta, withStateEnvelope } from "./schema";
import config from "../config";

// IndexedDB is the only durable browser store. Legacy localStorage / old IDB are read once at migration.

export const APP_STORAGE_KEY = "southDinkersAppState";

/** Documented legacy keys. Live app never reads (after migration flags) or writes/clears these. */
export const LEGACY_LOCAL_STORAGE_KEYS = [
  APP_STORAGE_KEY,
  "dm_voiceName",
  "dm_rate",
  "dm_pitch",
  "southDinkersLeaderboardDisplayUntil",
];

export const IDB_NAME = "southDinkersAppV2";
const LEGACY_IDB_NAME = "southDinkersApp";
export const IDB_STORE = "kv";
export const IDB_ENTITIES = "entities";
export const IDB_VERSION = 2;

const STATE_RECORD_KEY = APP_STORAGE_KEY;
export const IDB_RECORD_KEY = STATE_RECORD_KEY;
const APP_MIGRATION_FLAG_KEY = "southDinkersAppStateMigratedV2";
const VOICE_RECORD_KEY = "voicePrefs";
const VOICE_MIGRATION_FLAG_KEY = "voicePrefsMigratedV2";
const LEADERBOARD_RECORD_KEY = "southDinkersLeaderboardDisplayUntil";
const LEADERBOARD_MIGRATION_FLAG_KEY = "leaderboardDisplayMigratedV2";

const CALENDAR_PERSIST_KEYS = ["bookings", "calendarCourts", "bookingsV2", "slotsV2"];

const memoryKv = new Map();
let idbUnavailable = false;

export class StorageUnavailableError extends Error {
  constructor(message = "IndexedDB is unavailable. Allow site data for this browser and reload.") {
    super(message);
    this.name = "StorageUnavailableError";
  }
}

export function isDisplaySurface() {
  if (typeof window === "undefined") return false;
  if (window.name === "dink_display") return true;
  const hash = String(window.location.hash || "");
  if (/(^#\/display(?:\/|$|\?)|^#display(?:\/|$|\?))/.test(hash)) return true;
  const path = String(window.location.pathname || "");
  return /\/display\/?$/.test(path);
}

const supportsIndexedDB = () =>
  typeof indexedDB !== "undefined" && indexedDB !== null && !idbUnavailable;

function shouldUseMemoryKv() {
  return process.env.NODE_ENV === "test" || !supportsIndexedDB();
}

export function sanitizePersistState(state = {}) {
  const sanitized = { ...state };
  CALENDAR_PERSIST_KEYS.forEach((key) => {
    delete sanitized[key];
  });
  delete sanitized.isDemoMode;
  return sanitized;
}

function parsePersistedRaw(raw) {
  if (!raw) return null;
  const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
  if (!parsed || typeof parsed !== "object") return null;

  const legacyMeta = parsed.meta || {};
  const normalizedMeta = normalizeStateMeta({
    ...legacyMeta,
    seededAt: legacyMeta.seededAt || parsed.seededAt || null,
    seedSource: legacyMeta.seedSource || parsed.seedSource || null,
    seedLabel: legacyMeta.seedLabel || parsed.seedLabel || null,
    lastSavedAt:
      legacyMeta.lastSavedAt ||
      legacyMeta.savedAt ||
      parsed.lastSavedAt ||
      parsed.savedAt ||
      null,
    stateVersion: legacyMeta.stateVersion || parsed.version || CURRENT_STATE_VERSION,
  });

  const sanitized = sanitizePersistState(parsed);
  return {
    ...sanitized,
    meta: normalizedMeta,
    version: parsed.version || CURRENT_STATE_VERSION,
  };
}

export function getStateSavedAt(state) {
  const raw = state?.meta?.lastSavedAt || state?.lastSavedAt || state?.savedAt || null;
  if (!raw) return 0;
  const t = new Date(raw).getTime();
  return Number.isFinite(t) ? t : 0;
}

/** @deprecated No longer trims sessions; returns input unchanged for IndexedDB persistence. */
export function compactOpSessionsForStorage(sessions = []) {
  return sessions;
}

function sessionFreshness(session) {
  if (!session) return 0;
  const players = Array.isArray(session.players) ? session.players.length : 0;
  const matches = Array.isArray(session.matches) ? session.matches.length : 0;
  const completed = String(session.status || "").toLowerCase() === "completed" ? 1_000_000 : 0;
  return completed + players * 100 + matches + (session.endedAt || session.startedAt || 0) / 1e13;
}

export function mergeOpSessions(local = [], remote = []) {
  const map = new Map();
  [...(Array.isArray(local) ? local : []), ...(Array.isArray(remote) ? remote : [])].forEach((s) => {
    if (!s?.id) return;
    const existing = map.get(s.id);
    if (!existing || sessionFreshness(s) >= sessionFreshness(existing)) {
      map.set(s.id, s);
    }
  });
  return Array.from(map.values());
}

export function pickNewerState(a, b) {
  if (!a) return b || null;
  if (!b) return a;
  const merged = {
    ...(getStateSavedAt(b) > getStateSavedAt(a) ? b : a),
    opSessions: mergeOpSessions(a.opSessions, b.opSessions),
  };
  return merged;
}

export function isQuotaExceededError(err) {
  if (!err) return false;
  return (
    err.name === "QuotaExceededError" ||
    err.name === "NS_ERROR_DOM_QUOTA_REACHED" ||
    err.code === 22 ||
    err.code === 1014
  );
}

export const DB_VERSION_EVENT = "sd-db-versionchange";
const DB_BLOCK_TIMEOUT_MS = 4000;

function notifyDbVersionChange(reason) {
  if (typeof window === "undefined" || typeof window.dispatchEvent !== "function") return;
  try {
    window.dispatchEvent(new CustomEvent(DB_VERSION_EVENT, { detail: { reason } }));
  } catch (err) {
    console.warn("Database version notice failed", err);
  }
}

function openNamedDb(dbName, version, watchVersion) {
  return new Promise((resolve, reject) => {
    if (!supportsIndexedDB()) {
      reject(new StorageUnavailableError());
      return;
    }
    const req = indexedDB.open(dbName, version);
    let settled = false;
    let blockTimer = 0;
    const finish = (err, db) => {
      if (settled) return;
      settled = true;
      if (blockTimer) clearTimeout(blockTimer);
      if (err) reject(err);
      else resolve(db);
    };
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(IDB_STORE)) {
        db.createObjectStore(IDB_STORE);
      }
      // Create the entity store only. Never clear or rewrite kv here.
      if (dbName === IDB_NAME && !db.objectStoreNames.contains(IDB_ENTITIES)) {
        db.createObjectStore(IDB_ENTITIES, { keyPath: "key" });
      }
    };
    const armBlockTimer = () => {
      if (!watchVersion || blockTimer) return;
      notifyDbVersionChange("blocked");
      blockTimer = setTimeout(() => {
        try {
          if (req.result) req.result.close();
        } catch (err) { /* connection already closing */ }
        finish(new Error("Close other South Dinkers tabs and reload. IndexedDB upgrade is blocked by another tab."));
      }, DB_BLOCK_TIMEOUT_MS);
    };
    req.onblocked = () => {
      armBlockTimer();
    };
    req.onsuccess = () => {
      const db = req.result;
      if (watchVersion) {
        db.onversionchange = () => {
          try { db.close(); } catch (err) { /* connection already closing */ }
          notifyDbVersionChange("versionchange");
          try {
            if (
              process.env.NODE_ENV !== "test"
              && typeof window !== "undefined"
              && typeof window.location?.reload === "function"
            ) {
              window.location.reload();
            }
          } catch (err) { /* jsdom has no navigation */ }
        };
      }
      finish(null, db);
    };
    req.onerror = () => finish(req.error || new StorageUnavailableError());
  });
}

export function openSouthDinkersDb() {
  return openNamedDb(IDB_NAME, IDB_VERSION, true);
}

function openIdb(dbName = IDB_NAME) {
  if (dbName === IDB_NAME) return openSouthDinkersDb();
  return openNamedDb(dbName, 1, false);
}

export function isIdbDisabled() {
  return !supportsIndexedDB();
}

export function parseEnvelope(raw) {
  try {
    return parsePersistedRaw(raw);
  } catch (err) {
    console.error("Failed to parse persisted record", err);
    return null;
  }
}

export function readKvRecord(key) {
  return kvGet(key);
}

function kvGet(key) {
  if (shouldUseMemoryKv()) {
    return Promise.resolve(memoryKv.has(key) ? memoryKv.get(key) : null);
  }
  return openIdb().then(
    (db) =>
      new Promise((resolve, reject) => {
        const tx = db.transaction(IDB_STORE, "readonly");
        const req = tx.objectStore(IDB_STORE).get(key);
        req.onsuccess = () => {
          db.close();
          resolve(req.result ?? null);
        };
        req.onerror = () => {
          db.close();
          reject(req.error);
        };
      })
  );
}

function kvSetDirect(key, value) {
  if (shouldUseMemoryKv()) return Promise.resolve(true);
  return openIdb().then(
    (db) =>
      new Promise((resolve, reject) => {
        const tx = db.transaction(IDB_STORE, "readwrite");
        tx.oncomplete = () => {
          db.close();
          resolve(true);
        };
        tx.onerror = () => {
          db.close();
          reject(tx.error);
        };
        tx.objectStore(IDB_STORE).put(value, key);
      })
  );
}

/** Per-key serialized writes: monotonic seq; stale queued writes are skipped. */
const kvWriteLanes = new Map();

let testWriteDelayMs = 0;

/** @internal tests */
export function __setTestWriteDelayMs(ms) {
  testWriteDelayMs = Number(ms) || 0;
}

function getKvWriteLane(key) {
  if (!kvWriteLanes.has(key)) {
    kvWriteLanes.set(key, { chain: Promise.resolve(), seq: 0, committedSeq: 0 });
  }
  return kvWriteLanes.get(key);
}

function resetKvWriteLanes() {
  kvWriteLanes.clear();
}

async function maybeTestWriteDelay() {
  if (testWriteDelayMs > 0) {
    await new Promise((resolve) => setTimeout(resolve, testWriteDelayMs));
  }
}

/**
 * Queue a durable KV write. Returns { ok, stale?, error? } for this request.
 * Latest seq wins; older queued writes no-op before touching IDB.
 */
function enqueueSerializedKvWrite(key, value) {
  const lane = getKvWriteLane(key);
  lane.seq += 1;
  const seq = lane.seq;

  return new Promise((resolve) => {
    lane.chain = lane.chain.then(async () => {
      if (seq < lane.seq) {
        resolve({ ok: true, stale: true, seq });
        return;
      }

      await maybeTestWriteDelay();

      if (seq < lane.seq) {
        resolve({ ok: true, stale: true, seq });
        return;
      }

      memoryKv.set(key, value);
      try {
        await kvSetDirect(key, value);
        lane.committedSeq = seq;
        resolve({ ok: true, stale: false, seq });
      } catch (err) {
        console.error(`IndexedDB save failed for ${key}`, err);
        resolve({ ok: false, stale: false, seq, error: err });
      }
    });
  });
}

/**
 * One readwrite transaction: re-read record + flag; write both only if BOTH missing.
 * No async work inside the transaction (callback-driven reads + puts).
 */
function conditionalMigratePairInTransaction(db, recordKey, flagKey, recordValue, flagValue) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(IDB_STORE, "readwrite");
    const store = tx.objectStore(IDB_STORE);
    let recordRaw = null;
    let flagRaw = null;
    let readsDone = 0;
    let wrote = false;

    const onBothReads = () => {
      const hasRecord = recordRaw != null && recordRaw !== "";
      const hasFlag = flagRaw != null;
      if (hasRecord || hasFlag) {
        return;
      }
      wrote = true;
      store.put(recordValue, recordKey);
      store.put(flagValue, flagKey);
    };

    const recordReq = store.get(recordKey);
    recordReq.onsuccess = () => {
      recordRaw = recordReq.result ?? null;
      readsDone += 1;
      if (readsDone === 2) onBothReads();
    };
    recordReq.onerror = () => reject(recordReq.error);

    const flagReq = store.get(flagKey);
    flagReq.onsuccess = () => {
      flagRaw = flagReq.result ?? null;
      readsDone += 1;
      if (readsDone === 2) onBothReads();
    };
    flagReq.onerror = () => reject(flagReq.error);

    tx.oncomplete = () => {
      resolve({
        wrote,
        recordRaw: recordRaw != null && recordRaw !== "" ? recordRaw : wrote ? recordValue : null,
        hadRecord: recordRaw != null && recordRaw !== "",
        hadFlag: flagRaw != null,
      });
    };
    tx.onerror = () => reject(tx.error || new Error("IndexedDB transaction failed"));
    tx.onabort = () => reject(tx.error || new Error("IndexedDB transaction aborted"));
  });
}

let memoryMigrationChain = Promise.resolve();

function conditionalMigratePairInMemory(recordKey, flagKey, recordValue, flagValue) {
  memoryMigrationChain = memoryMigrationChain.then(() => {
    const recordRaw = memoryKv.has(recordKey) ? memoryKv.get(recordKey) : null;
    const flagRaw = memoryKv.has(flagKey) ? memoryKv.get(flagKey) : null;
    const hasRecord = recordRaw != null && recordRaw !== "";
    const hasFlag = flagRaw != null;
    if (hasRecord || hasFlag) {
      return {
        wrote: false,
        recordRaw: hasRecord ? recordRaw : null,
        hadRecord: hasRecord,
        hadFlag: hasFlag,
      };
    }
    memoryKv.set(recordKey, recordValue);
    memoryKv.set(flagKey, flagValue);
    return { wrote: true, recordRaw: recordValue, hadRecord: false, hadFlag: false };
  });
  return memoryMigrationChain;
}

async function readRecordAndFlag(recordKey, flagKey) {
  const recordRaw = await kvGet(recordKey);
  const flagRaw = await kvGet(flagKey);
  return { recordRaw, flagRaw };
}

function readLegacyLocalStorageRaw() {
  if (typeof window === "undefined" || !window.localStorage) return null;
  try {
    return window.localStorage.getItem(APP_STORAGE_KEY);
  } catch {
    return null;
  }
}

function readLegacyLocalStorageState() {
  try {
    return parsePersistedRaw(readLegacyLocalStorageRaw());
  } catch (err) {
    console.error("Failed to read legacy localStorage app state", err);
    return null;
  }
}

function readLegacyIdbKvState() {
  if (shouldUseMemoryKv()) {
    const raw = memoryKv.get(`legacy:${APP_STORAGE_KEY}`);
    return raw ? parsePersistedRaw(raw) : null;
  }
  if (!supportsIndexedDB()) return Promise.resolve(null);
  return openIdb(LEGACY_IDB_NAME)
    .then((db) =>
      new Promise((resolve, reject) => {
        const tx = db.transaction(IDB_STORE, "readonly");
        const req = tx.objectStore(IDB_STORE).get(APP_STORAGE_KEY);
        req.onsuccess = () => {
          db.close();
          resolve(parsePersistedRaw(req.result || null));
        };
        req.onerror = () => {
          db.close();
          reject(req.error);
        };
      })
    )
    .catch(() => null);
}

export function buildCleanPersistedState() {
  const courts = config.getDefaultCourts().map((court) => ({
    ...court,
    players: court.players || [],
    teamGreen: court.teamGreen || [],
    teamBlue: court.teamBlue || [],
    timer: court.timer || {
      startTime: null,
      lastResumedAt: null,
      accumulatedMs: 0,
      isPaused: false,
    },
    currentMatchId: court.currentMatchId ?? null,
    locked: !!court.locked,
    lockReason: court.lockReason || null,
    lockedUntil: court.lockedUntil ?? null,
  }));

  return withStateEnvelope({
    settings: {
      defaultQueueCourts: config.calendar?.courts?.length || courts.length,
      defaultCalendarCourts: config.calendar?.courts?.length || courts.length,
      defaultOpFee: config.pricing?.openPlayRate ?? 250,
      defaultRentalRate: config.pricing?.rentalRate ?? 600,
      calendarOpenHour: config.calendar?.openHour ?? 8,
      calendarCloseHour: config.calendar?.closeHour ?? 22,
    },
    courts,
    players: [],
    matchQueue: [],
    requestedMatches: [],
    partners: [],
    teams: [],
    matches: [],
    currentOpSession: null,
    opSessions: [],
    userRole: null,
    staffName: "",
    meta: {
      seededAt: new Date().toISOString(),
      seedLabel: "idb-clean-v2",
      seedSource: "indexeddb",
    },
  });
}

function importLegacyAppState(lsState, idbState) {
  const picked = pickNewerState(lsState, idbState);
  if (!picked) return null;
  return withStateEnvelope({
    ...picked,
    meta: {
      ...(picked.meta || {}),
      seedLabel: picked.meta?.seedLabel || "idb-import-legacy",
      seedSource: "legacy-import",
    },
  });
}

async function bootstrapAppStateRecord() {
  const quick = await readRecordAndFlag(STATE_RECORD_KEY, APP_MIGRATION_FLAG_KEY);
  const hasRecord =
    quick.recordRaw != null && quick.recordRaw !== "";
  const hasFlag = quick.flagRaw != null;
  if (hasRecord) {
    const parsed = parsePersistedRaw(quick.recordRaw);
    memoryKv.set(STATE_RECORD_KEY, quick.recordRaw);
    return parsed;
  }
  if (hasFlag) {
    return buildCleanPersistedState();
  }

  const legacyIdbState = await readLegacyIdbKvState();
  const legacyLsState = readLegacyLocalStorageState();
  const legacyImport = importLegacyAppState(legacyLsState, legacyIdbState);
  const toWrite = legacyImport || buildCleanPersistedState();
  const json = JSON.stringify(toWrite);
  const flagValue = new Date().toISOString();

  if (shouldUseMemoryKv()) {
    const outcome = await conditionalMigratePairInMemory(
      STATE_RECORD_KEY,
      APP_MIGRATION_FLAG_KEY,
      json,
      flagValue
    );
    const raw = outcome.recordRaw ?? (await kvGet(STATE_RECORD_KEY));
    if (raw) memoryKv.set(STATE_RECORD_KEY, raw);
    return parsePersistedRaw(raw) || buildCleanPersistedState();
  }

  const db = await openIdb();
  try {
    const outcome = await conditionalMigratePairInTransaction(
      db,
      STATE_RECORD_KEY,
      APP_MIGRATION_FLAG_KEY,
      json,
      flagValue
    );
    const raw = outcome.recordRaw ?? (await kvGet(STATE_RECORD_KEY));
    if (raw) memoryKv.set(STATE_RECORD_KEY, raw);
    return parsePersistedRaw(raw) || buildCleanPersistedState();
  } finally {
    db.close();
  }
}

let voiceCache = { voiceName: "", rate: 0.9, pitch: 1 };
let leaderboardCache = { until: 0, mode: "full" };

function readLegacyVoiceFromLocalStorage() {
  if (typeof window === "undefined" || !window.localStorage) {
    return { voiceName: "", rate: 0.9, pitch: 1 };
  }
  const rate = Number(window.localStorage.getItem("dm_rate"));
  const pitch = Number(window.localStorage.getItem("dm_pitch"));
  return {
    voiceName: window.localStorage.getItem("dm_voiceName") || "",
    rate: Number.isFinite(rate) ? rate : 0.9,
    pitch: Number.isFinite(pitch) ? pitch : 1,
  };
}

function readLegacyLeaderboardFromLocalStorage() {
  if (typeof window === "undefined" || !window.localStorage) {
    return { until: 0, mode: "full" };
  }
  try {
    const raw = window.localStorage.getItem(LEADERBOARD_RECORD_KEY);
    if (!raw) return { until: 0, mode: "full" };
    if (raw.startsWith("{")) {
      const parsed = JSON.parse(raw);
      return {
        until: Number(parsed.until) || 0,
        mode: parsed.mode === "top5" ? "top5" : "full",
      };
    }
    const n = Number(raw);
    return { until: Number.isFinite(n) ? n : 0, mode: "full" };
  } catch {
    return { until: 0, mode: "full" };
  }
}

function applyVoiceRecordRaw(raw) {
  if (raw == null) return;
  const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
  voiceCache = { ...voiceCache, ...parsed };
}

function applyLeaderboardRecordRaw(raw) {
  if (raw == null) return;
  const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
  leaderboardCache = {
    until: Number(parsed.until) || 0,
    mode: parsed.mode === "top5" ? "top5" : "full",
  };
}

async function migrateVoicePrefsInIdb() {
  const quick = await readRecordAndFlag(VOICE_RECORD_KEY, VOICE_MIGRATION_FLAG_KEY);
  const hasRecord = quick.recordRaw != null;
  const hasFlag = quick.flagRaw != null;
  if (hasRecord || hasFlag) {
    if (hasRecord) applyVoiceRecordRaw(quick.recordRaw);
    return;
  }

  const legacy = readLegacyVoiceFromLocalStorage();
  const candidate = { ...legacy, migratedAt: new Date().toISOString() };
  const recordJson = JSON.stringify(candidate);
  const flagValue = new Date().toISOString();

  if (shouldUseMemoryKv()) {
    const outcome = await conditionalMigratePairInMemory(
      VOICE_RECORD_KEY,
      VOICE_MIGRATION_FLAG_KEY,
      recordJson,
      flagValue
    );
    applyVoiceRecordRaw(outcome.recordRaw ?? (await kvGet(VOICE_RECORD_KEY)));
    return;
  }

  const db = await openIdb();
  try {
    const outcome = await conditionalMigratePairInTransaction(
      db,
      VOICE_RECORD_KEY,
      VOICE_MIGRATION_FLAG_KEY,
      recordJson,
      flagValue
    );
    applyVoiceRecordRaw(outcome.recordRaw ?? (await kvGet(VOICE_RECORD_KEY)));
  } finally {
    db.close();
  }
}

async function migrateLeaderboardDisplayInIdb() {
  const quick = await readRecordAndFlag(LEADERBOARD_RECORD_KEY, LEADERBOARD_MIGRATION_FLAG_KEY);
  const hasRecord = quick.recordRaw != null;
  const hasFlag = quick.flagRaw != null;
  if (hasRecord || hasFlag) {
    if (hasRecord) applyLeaderboardRecordRaw(quick.recordRaw);
    return;
  }

  const legacy = readLegacyLeaderboardFromLocalStorage();
  const recordJson = JSON.stringify(legacy);
  const flagValue = new Date().toISOString();

  if (shouldUseMemoryKv()) {
    const outcome = await conditionalMigratePairInMemory(
      LEADERBOARD_RECORD_KEY,
      LEADERBOARD_MIGRATION_FLAG_KEY,
      recordJson,
      flagValue
    );
    applyLeaderboardRecordRaw(outcome.recordRaw ?? (await kvGet(LEADERBOARD_RECORD_KEY)));
    return;
  }

  const db = await openIdb();
  try {
    const outcome = await conditionalMigratePairInTransaction(
      db,
      LEADERBOARD_RECORD_KEY,
      LEADERBOARD_MIGRATION_FLAG_KEY,
      recordJson,
      flagValue
    );
    applyLeaderboardRecordRaw(outcome.recordRaw ?? (await kvGet(LEADERBOARD_RECORD_KEY)));
  } finally {
    db.close();
  }
}

/**
 * Hydrate all persisted data before the first React render.
 * Throws StorageUnavailableError when IndexedDB cannot be used (non-test).
 */
async function finishHydrate(state) {
  await migrateVoicePrefsInIdb();
  await migrateLeaderboardDisplayInIdb();
  let adopted = null;
  try {
    const { loadAuthoritativeState } = await import("./entityStore");
    adopted = await loadAuthoritativeState({ bootstrapped: state });
  } catch (err) {
    console.warn("Entity store unavailable; using the kv document", err);
  }
  // Jest keeps the kv document as the returned snapshot so existing save/load
  // tests stay on the memory store. Live reads use the entity projection.
  if (process.env.NODE_ENV !== "test" && adopted) return adopted;
  return state;
}

let hydrateInflight = null;

export function hydratePersistedState() {
  if (!hydrateInflight) {
    hydrateInflight = hydratePersistedStateOnce().finally(() => {
      hydrateInflight = null;
    });
  }
  return hydrateInflight;
}

async function hydratePersistedStateOnce() {
  if (typeof window !== "undefined" && window.__sdPreseed) {
    try {
      await window.__sdPreseed;
    } catch (err) {
      console.warn("Preseed wait failed", err);
    }
  }
  if (typeof indexedDB === "undefined" && process.env.NODE_ENV !== "test") {
    throw new StorageUnavailableError();
  }
  try {
    const state = await bootstrapAppStateRecord();
    return await finishHydrate(state);
  } catch (err) {
    if (process.env.NODE_ENV === "test") {
      idbUnavailable = true;
      const state = await bootstrapAppStateRecord();
      return await finishHydrate(state);
    }
    throw err instanceof StorageUnavailableError ? err : new StorageUnavailableError(err?.message);
  }
}

function buildStoredPayload(state = {}) {
  const toStore = withStateEnvelope(sanitizePersistState(state));
  return { toStore };
}

export async function persistAppState(state = {}) {
  if (isDisplaySurface()) {
    const { toStore } = buildStoredPayload(state);
    return { ok: true, payload: toStore, compacted: false, error: null, skipped: true };
  }

  let toStore;
  try {
    toStore = buildStoredPayload(state).toStore;
  } catch (err) {
    console.error("Failed to build persisted state", err);
    return { ok: false, payload: null, compacted: false, error: err };
  }

  const json = JSON.stringify(toStore);
  const write = await enqueueSerializedKvWrite(STATE_RECORD_KEY, json);
  if (write.stale) {
    return { ok: true, payload: toStore, compacted: false, error: null, stale: true };
  }
  if (!write.ok) {
    return { ok: false, payload: toStore, compacted: false, error: write.error };
  }
  return { ok: true, payload: toStore, compacted: false, error: null, stale: false };
}

export function saveStateSync(state = {}, callbacks) {
  if (isDisplaySurface()) {
    const { toStore } = buildStoredPayload(state);
    return toStore;
  }

  try {
    const { toStore } = buildStoredPayload(state);
    const json = JSON.stringify(toStore);
    memoryKv.set(STATE_RECORD_KEY, json);

    if (shouldUseMemoryKv()) {
      callbacks?.onPersisted?.();
      return toStore;
    }

    enqueueSerializedKvWrite(STATE_RECORD_KEY, json)
      .then((write) => {
        if (write.ok && !write.stale) callbacks?.onPersisted?.();
        else if (!write.ok) callbacks?.onError?.(write.error);
      })
      .catch((err) => {
        console.error("IndexedDB save failed", err);
        callbacks?.onError?.(err);
      });

    return toStore;
  } catch (err) {
    console.error("Failed to save state", err);
    callbacks?.onError?.(err);
    return null;
  }
}

export async function saveState(state = {}) {
  const result = await persistAppState(state);
  return result.payload;
}

/** @deprecated Live reads use hydrated memory cache only. */
export function loadState() {
  const raw = memoryKv.get(STATE_RECORD_KEY);
  if (!raw) return null;
  try {
    return parsePersistedRaw(raw);
  } catch (err) {
    console.error("Failed to load state", err);
    return null;
  }
}

export async function loadStateFromIndexedDB() {
  const raw = await kvGet(STATE_RECORD_KEY);
  return parsePersistedRaw(raw);
}

export function rememberVoicePrefs(prefs = {}) {
  const rate = Number(prefs.rate);
  const pitch = Number(prefs.pitch);
  voiceCache = {
    voiceName: prefs.voiceName || "",
    rate: Number.isFinite(rate) ? rate : 0.9,
    pitch: Number.isFinite(pitch) ? pitch : 1,
  };
}

export function rememberLeaderboardDisplay(payload = {}) {
  leaderboardCache = {
    until: Number(payload.until) || 0,
    mode: payload.mode === "top5" ? "top5" : "full",
  };
}

export function getVoicePrefsSync() {
  return {
    voiceName: voiceCache.voiceName || "",
    rate: Number.isFinite(Number(voiceCache.rate)) ? Number(voiceCache.rate) : 0.9,
    pitch: Number.isFinite(Number(voiceCache.pitch)) ? Number(voiceCache.pitch) : 1,
  };
}

export async function saveVoicePrefs(prefs = {}) {
  if (isDisplaySurface()) {
    return { ok: true, stale: false, prefs: getVoicePrefsSync() };
  }
  voiceCache = {
    ...getVoicePrefsSync(),
    ...prefs,
    migratedAt: voiceCache.migratedAt || new Date().toISOString(),
  };
  const json = JSON.stringify(voiceCache);
  const write = await enqueueSerializedKvWrite(VOICE_RECORD_KEY, json);
  return {
    ok: write.ok,
    stale: !!write.stale,
    error: write.error,
    prefs: getVoicePrefsSync(),
  };
}

export function getLeaderboardDisplaySync() {
  return {
    until: Number(leaderboardCache.until) || 0,
    mode: leaderboardCache.mode === "top5" ? "top5" : "full",
  };
}

export async function saveLeaderboardDisplay(payload = {}) {
  if (isDisplaySurface()) {
    return { ok: true, stale: false, display: getLeaderboardDisplaySync() };
  }
  leaderboardCache = {
    until: Number(payload.until) || 0,
    mode: payload.mode === "top5" ? "top5" : "full",
  };
  const json = JSON.stringify(leaderboardCache);
  const write = await enqueueSerializedKvWrite(LEADERBOARD_RECORD_KEY, json);
  return {
    ok: write.ok,
    stale: !!write.stale,
    error: write.error,
    display: getLeaderboardDisplaySync(),
  };
}

/** @deprecated use saveLeaderboardDisplay */
export function saveLeaderboardDisplaySync(payload = {}) {
  void saveLeaderboardDisplay(payload);
  return getLeaderboardDisplaySync();
}

export function resetStorageForTests() {
  memoryKv.clear();
  memoryMigrationChain = Promise.resolve();
  resetKvWriteLanes();
  testWriteDelayMs = 0;
  idbUnavailable = false;
  voiceCache = { voiceName: "", rate: 0.9, pitch: 1 };
  leaderboardCache = { until: 0, mode: "full" };
  if (typeof window !== "undefined" && typeof window.__sdResetEntities === "function") {
    window.__sdResetEntities();
  }
  hydrateInflight = null;
}

export function readKvRawForTests(key = STATE_RECORD_KEY) {
  return memoryKv.has(key) ? memoryKv.get(key) : null;
}

export function deleteKvForTests(key) {
  memoryKv.delete(key);
}

/** @internal tests — seed legacy IDB kv backup */
export function seedLegacyIdbKvForTests(serialized) {
  memoryKv.set(`legacy:${APP_STORAGE_KEY}`, serialized);
}
