import React, { useState } from 'react';
import { ArrowRightLeft, X } from 'lucide-react';

export default function MoveMatchModal({ isOpen, onClose, fromCourtName, courts, onMove }) {
    const [targetId, setTargetId] = useState(null);

    // Filter for empty courts only
    const availableCourts = courts.filter(c => c.players.length === 0);

    const handleConfirm = () => {
        if (targetId) {
            onMove(targetId);
            onClose();
        }
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 backdrop-blur-sm">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-sm mx-4 p-6 border border-pt-teal/10">
                <div className="flex items-center justify-between mb-4">
                    <h2 className="text-lg font-bold text-pt-teal flex items-center gap-2">
                        <ArrowRightLeft className="w-5 h-5" />
                        Move Match
                    </h2>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                <p className="mb-4 text-sm text-slate-600">
                    Moving match from <strong>{fromCourtName}</strong>. Select an empty court to move to:
                </p>

                <div className="space-y-2 max-h-60 overflow-y-auto mb-6 pr-1">
                    {availableCourts.length === 0 ? (
                        <p className="text-sm text-center text-slate-400 py-4 italic bg-slate-50 rounded-lg">No empty courts available.</p>
                    ) : (
                        availableCourts.map(court => (
                            <button
                                key={court.id}
                                onClick={() => setTargetId(court.id)}
                                className={`w-full text-left px-4 py-3 rounded-xl border transition-all ${targetId === court.id
                                        ? "bg-pt-teal text-white border-pt-teal shadow-md ring-2 ring-pt-teal/20"
                                        : "bg-white text-slate-700 border-slate-100 hover:border-pt-teal/30 hover:bg-slate-50"
                                    }`}
                            >
                                <span className="font-display font-bold tracking-wide">{court.name}</span>
                            </button>
                        ))
                    )}
                </div>

                <div className="flex justify-end gap-3">
                    <button
                        onClick={onClose}
                        className="px-4 py-2 text-sm font-medium text-slate-500 hover:bg-slate-100 rounded-lg transition-colors"
                    >
                        Cancel
                    </button>
                    <button
                        onClick={handleConfirm}
                        disabled={!targetId}
                        className={`px-6 py-2 text-sm font-bold rounded-full transition-all shadow-sm ${targetId
                                ? "bg-pt-teal text-white hover:bg-pt-teal/90 hover:shadow-md"
                                : "bg-slate-100 text-slate-400 cursor-not-allowed"
                            }`}
                    >
                        Confirm Move
                    </button>
                </div>
            </div>
        </div>
    );
}
