/**
 * Shared schema utilities for the persisted application state.
 *
 * Keep additions backwards compatible by bumping the CURRENT_STATE_VERSION
 * and documenting the change in docs/schema-history.md.
 */

export const CURRENT_STATE_VERSION = 5;

/**
 * Optional fields on Player (and on players snapshotted inside OpSession).
 * Absent on older IndexedDB records. Do not backfill by guessing.
 *
 * - referenceId: Reclub participant reference, stored unchanged.
 *   When referenceType === 3 (guest / +1) this is not a Reclub user id.
 * - referenceType: Reclub participant type when the import supplied it. 3 means guest.
 * - reclubUserId: Reclub user id for a non-guest import. Null for guests and manual players.
 * - isGuest: true only when the player was imported as a guest (referenceType === 3).
 *
 * Readers may copy referenceId onto reclubUserId only when a non-guest signal is
 * already stored (isGuest === false, referenceType other than 3, or reclubUserId itself).
 * A bare referenceId is not that signal.
 */
export const PLAYER_OPTIONAL_RECLUB_FIELDS = [
  "referenceId",
  "referenceType",
  "reclubUserId",
  "isGuest",
];

export function normalizeStateMeta(meta = {}) {
  return {
    stateVersion: meta.stateVersion || CURRENT_STATE_VERSION,
    seededAt: meta.seededAt || null,
    seedSource: meta.seedSource || null,
    seedLabel: meta.seedLabel || null,
    lastSavedAt: meta.lastSavedAt || null,
    migrations:
      meta.migrations && typeof meta.migrations === "object"
        ? { ...meta.migrations }
        : {},
  };
}

export function buildStateMeta(overrides = {}) {
  const timestamp = overrides.lastSavedAt || new Date().toISOString();
  return normalizeStateMeta({
    ...overrides,
    lastSavedAt: timestamp,
    stateVersion: overrides.stateVersion || CURRENT_STATE_VERSION,
  });
}

export function withStateEnvelope(state = {}, overrides = {}) {
  const meta = buildStateMeta({
    ...(state.meta || {}),
    ...overrides,
  });

  return {
    ...state,
    meta,
    version: CURRENT_STATE_VERSION,
  };
}

export const STATE_SHAPE = {
  settings: "ClubSettings",
  courts: "Court[]",
  players: "Player[] (optional reclub fields: referenceId, referenceType, reclubUserId, isGuest)",
  matchQueue: "MatchQueueEntry[]",
  matches: "Match[]",
  currentOpSession: "OpSession | null",
  opSessions: "OpSession[]",
  bookings: "Booking[]",
  calendarCourts: "CalendarCourt[]",
};

export function describeStateSchema() {
  return Object.entries(STATE_SHAPE).map(([key, type]) => `${key}: ${type}`);
}
